#!/bin/bash
# One-command installer for the CME portal on a fresh Ubuntu droplet.
# Self-contained: the whole portal is packed inside this file.
# Usage (as root, in the droplet console):
#   curl -fsSL https://raw.githubusercontent.com/USER/cme-portal/main/install.sh | bash -s -- cme.yourdomain.com AdminPassword
set -e
DOMAIN="$1"; PASS="$2"
if [ -z "$DOMAIN" ] || [ -z "$PASS" ]; then
  echo "Usage: install.sh <domain> <admin-password>"; exit 1
fi
export DEBIAN_FRONTEND=noninteractive
APT="apt-get -o DPkg::Lock::Timeout=600 -y"

echo "==> [1/6] Updating system"
$APT update
$APT install curl git ufw gnupg debian-keyring debian-archive-keyring apt-transport-https

echo "==> [2/6] Installing Node.js 20"
if ! command -v node >/dev/null || ! node -v | grep -q '^v2[0-9]'; then
  curl -fsSL https://deb.nodesource.com/setup_20.x | bash -
  $APT install nodejs
fi

echo "==> [3/6] Installing Caddy (automatic HTTPS)"
if ! command -v caddy >/dev/null; then
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' | gpg --batch --yes --dearmor -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
  curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' > /etc/apt/sources.list.d/caddy-stable.list
  $APT update
  $APT install caddy
fi

echo "==> [4/6] Unpacking the portal"
PAYLOAD=""
rm -rf /opt/cme-app && mkdir -p /opt/cme-app
echo "$PAYLOAD" | base64 -d | tar xz -C /opt/cme-app
mkdir -p /opt/cme-data

echo "==> [5/6] Starting the portal service"
cat > /etc/systemd/system/cme.service <<EOF
[Unit]
Description=CME Attendance Portal
After=network.target

[Service]
WorkingDirectory=/opt/cme-app
ExecStart=/usr/bin/node /opt/cme-app/server.js
Environment="ADMIN_PASSWORD=$PASS"
Environment="PORT=3000"
Environment="DATA_DIR=/opt/cme-data"
Restart=always
RestartSec=3

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable cme >/dev/null 2>&1
systemctl restart cme

cat > /etc/caddy/Caddyfile <<EOF
$DOMAIN {
    request_body {
        max_size 20MB
    }
    reverse_proxy localhost:3000
}
EOF
systemctl restart caddy

echo "==> [6/6] Opening firewall"
ufw allow OpenSSH >/dev/null
ufw allow 80/tcp >/dev/null
ufw allow 443/tcp >/dev/null
ufw --force enable >/dev/null

sleep 3
KEY=$(grep -o '"deskKey":"[a-z0-9]*"' /opt/cme-data/db.json | cut -d'"' -f4)
IP=$(curl -fsS https://api.ipify.org || echo "your-droplet-ip")
echo ""
echo "=============================================================="
echo " CME portal installed"
echo "   Admin panel   : https://$DOMAIN/admin"
echo "   Delegate link : https://$DOMAIN/apply"
echo "   Help-desk link: https://$DOMAIN/desk?k=$KEY"
echo ""
echo " DNS: make sure an A record for $DOMAIN points to $IP"
echo " HTTPS turns on automatically within a minute after DNS points here."
echo " Service status : systemctl status cme"
echo "=============================================================="
